  "voices.v1.tag": "팔자주름",
  "voices.v1.title": "\"필러보다 실리프팅이 맞았어요.\"",
  "voices.v1.desc": "\"처음엔 필러만 알아봤는데, 컨시어지가 피부 두께랑 처짐 정도 보고 실리프팅이 맞다고 알려줬어요. 결과 훨씬 자연스러워요.\"",
  "voices.v2.tag": "줄기세포",
  "voices.v2.title": "\"정품인지 확인하고 받았어요.\"",
  "voices.v2.desc": "\"줄기세포가 가격대가 큰데, 정품·집도의 직접 확인해주니 안심하고 받았습니다. 피부결이 완전히 바뀌었어요.\"",
  "voices.v3.tag": "탈모",
  "voices.v3.title": "\"3개 병원 비교 후 결정했어요.\"",
  "voices.v3.desc": "\"탈모 클리닉이 너무 많아서 못 정했는데, 3곳 객관적 비교 자료 받고 결정. 두피 스캘프 + 줄기세포 조합으로 효과 봤어요.\"",
  "voices.v4.tag": "안티에이징",
  "voices.v4.title": "\"검진부터 시작했어요.\"",
  "voices.v4.desc": "\"바로 시술 받지 말고 검진 먼저 권유해주셔서 좋았어요. 호르몬·영양 상태 보고 맞춤 프로그램 받으니 효과 더 컸어요.\"",
  "voices.v5.tag": "치료 (정형외과)",
  "voices.v5.title": "\"미국 대비 1/5 가격.\"",
  "voices.v5.desc": "\"미국에서 받으면 보험 없이 수천만원인데, 한국에서 동급 치료를 훨씬 저렴하게. 통역까지 붙어서 안심.\"",
  "voices.v6.tag": "힐링투어",
  "voices.v6.title": "\"검진 + 한방 + 관광 한 번에.\"",
  "voices.v6.desc": "\"시술만 받고 가기 아까웠는데, 검진·한방 체질 분석·대학로 공연까지 한 일정에 묶어주셔서 완벽한 휴가가 됐어요.\"",
  "voices.v7.tag": "K-pop Tour",
  "voices.v7.title": "\"뷰티 + 케이팝 투어 동시에.\"",
  "voices.v7.desc": "\"K-Beauty 시술 받으러 왔는데 뮤직비디오 촬영지까지 투어. 친구들한테 자랑할 추억 한가득.\"",
  "voices.v8.tag": "멤버십",
  "voices.v8.title": "\"매년 끊고 정기 케어 받아요.\"",
  "voices.v8.desc": "\"골드 멤버십으로 분기마다 케어. 가격도 할인되고 일정 짤 필요 없어서 시간 절약 엄청 큽니다.\"",
  "voices.v9.tag": "웰니스 (스파)",
  "voices.v9.title": "\"웰니스라운지 방배본점 추천 받았어요.\"",
  "voices.v9.desc": "\"시술 후 회복 동선에 마사지·힐링 스파까지 짜주셔서 완전 다른 차원의 회복. 다음에 또 올 거예요.\"",

