  "ai.sub": "The Wellness N kết nối Maloha — AI phiên dịch y tế thời gian thực của công ty đối tác Undermilli — với các bệnh viện đối tác, để bệnh nhân nước ngoài an tâm tư vấn và điều trị bằng tiếng mẹ đẻ.",
  "ai.tagline1": "AI phiên dịch y tế thời gian thực, không cần phiên dịch viên",
