export const DICTIONARIES: Record<Lang, Dict> = { ko, en, zh, ja, th, vi, id };

export function tFor(lang: Lang, key: string): string {
  return DICTIONARIES[lang]?.[key] ?? DICTIONARIES.ko[key] ?? key;
}
